result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/hex.ts", "content": "/**
 * Axial hex-grid math (pointy or flat top — math is identical).
 * Axial (q, r) maps to cube (x, y, z) as: x = q, z = r, y = -x - z.
 */
export interface Hex {
  q: number;
  r: number;
}

export const hex = (q: number, r: number): Hex => ({ q, r });

/** The 6 neighbor directions, in cube-space order. */
export const DIRECTIONS: readonly Hex[] = [
  hex(1, 0), // +x
  hex(1, -1), // +x, -z
  hex(0, -1), // -z
  hex(-1, 0), // -x
  hex(-1, 1), // -x, +z
  hex(0, 1), // +z
];

export const add = (a: Hex, b: Hex): Hex => hex(a.q + b.q, a.r + b.r);

export const subtract = (a: Hex, b: Hex): Hex => hex(a.q - b.q, a.r - b.r);

export const scale = (a: Hex, k: number): Hex => hex(a.q * k, a.r * k);

/** Neighbor in one of the 6 directions (0–5). */
export const neighbor = (h: Hex, direction: number): Hex =>
  add(h, DIRECTIONS[((direction % 6) + 6) % 6]);

/** Hex distance in axial coordinates. */
export function distance(a: Hex, b: Hex): number {
  const d = subtract(a, b);
  const dx = Math.abs(d.q);
  const dz = Math.abs(d.r);
  const dy = Math.abs(d.q + d.r); // dy = -(dx + dz)
  return Math.max(dx, dy, dz);
}

/** All hexes exactly `radius` away from `center` (clockwise ring). */
export function hexRing(center: Hex, radius: number): Hex[] {
  if (radius < 0) throw new RangeError(`radius must be >= 0, got ${radius}`);
  if (radius === 0) return [hex(center.q, center.r)];

  const results: Hex[] = [];
  // Start at center + direction(4) * radius, then walk each side.
  let current = add(center, scale(DIRECTIONS[4], radius));
  for (let side = 0; side < 6; side++) {
    for (let step = 0; step < radius; step++) {
      results.push(current);
      current = neighbor(current, side);
    }
  }
  return results;
}

/** Center plus all rings up to and including `radius`. */
export function hexSpiral(center: Hex, radius: number): Hex[] {
  if (radius < 0) throw new RangeError(`radius must be >= 0, got ${radius}`);
  const results: Hex[] = [hex(center.q, center.r)];
  for (let k = 1; k <= radius; k++) {
    results.push(...hexRing(center, k));
  }
  return results;
}

// --- Cube rounding for line drawing -----------------------------------------

const roundCube = (x: number, y: number, z: number): Hex => {
  let rx = Math.round(x);
  let ry = Math.round(y);
  let rz = Math.round(z);

  const dx = Math.abs(rx - x);
  const dy = Math.abs(ry - y);
  const dz = Math.abs(rz - z);

  if (dx > dy && dx > dz) {
    rx = -ry - rz;
  } else if (dy > dz) {
    ry = -rx - rz;
  } else {
    rz = -rx - ry;
  }
  return hex(rx, rz);
};

const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/**
 * Line from `a` to `b` (inclusive of both endpoints), via N = distance+1
 * samples lerped in cube space with cube rounding.
 */
export function hexLine(a: Hex, b: Hex): Hex[] {
  const n = distance(a, b);
  if (n === 0) return [hex(a.q, a.r)];

  const ax = a.q;
  const az = a.r;
  const ay = -ax - az;
  const bx = b.q;
  const bz = b.r;
  const by = -bx - bz;

  const results: Hex[] = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    results.push(roundCube(lerp(ax, bx, t), lerp(ay, by, t), lerp(az, bz, t)));
  }
  return results;
}
"})
