result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/hex.test.ts", "content": "import { describe, expect, it } from 'vitest';
import {
  DIRECTIONS,
  add,
  distance,
  hex,
  hexLine,
  hexRing,
  hexSpiral,
  neighbor,
  scale,
  subtract,
} from '../src/hex';

const key = (h: { q: number; r: number }) => `${h.q},${h.r}`;

const unique = (hexes: { q: number; r: number }[]): Set<string> =>
  new Set(hexes.map(key));

describe('distance', () => {
  it('distance((0,0),(2,-1)) === 2', () => {
    expect(distance(hex(0, 0), hex(2, -1))).toBe(2);
  });

  it('is symmetric and zero at origin', () => {
    const samples = [
      [hex(0, 0), hex(3, -2)],
      [hex(-4, 1), hex(2, 2)],
      [hex(5, -5), hex(0, 0)],
    ];
    for (const [a, b] of samples) {
      expect(distance(a, b)).toBe(distance(b, a));
      expect(distance(a, a)).toBe(0);
    }
  });
});

describe('neighbors', () => {
  it('has exactly 6 directions', () => {
    expect(DIRECTIONS).toHaveLength(6);
  });

  it("every hex's 6 neighbors are at distance 1", () => {
    const centers = hexSpiral(hex(0, 0), 3);
    for (const c of centers) {
      for (let d = 0; d < 6; d++) {
        expect(distance(c, neighbor(c, d))).toBe(1);
      }
    }
  });

  it('neighbor is invertible: opposite directions cancel out', () => {
    for (let d = 0; d < 6; d++) {
      const h = hex(3, -2);
      expect(subtract(add(h, scale(DIRECTIONS[d], 5)), scale(DIRECTIONS[d], 5))).toEqual(h);
    }
  });
});

describe('hexRing', () => {
  it('radius 2 returns exactly 12 unique hexes all at distance 2', () => {
    const ring = hexRing(hex(0, 0), 2);
    expect(ring).toHaveLength(12);
    expect(unique(ring).size).toBe(12);
    for (const h of ring) {
      expect(distance(hex(0, 0), h)).toBe(2);
    }
  });

  it('works off-origin', () => {
    const center = hex(-3, 7);
    const ring = hexRing(center, 4);
    expect(ring).toHaveLength(24);
    expect(unique(ring).size).toBe(24);
    for (const h of ring) {
      expect(distance(center, h)).toBe(4);
    }
  });

  it('radius 0 is just the center', () => {
    expect(hexRing(hex(2, -3), 0)).toEqual([hex(2, -3)]);
  });
});

describe('hexSpiral', () => {
  it('radius 2 returns 19 hexes (1+6+12) with no duplicates', () => {
    const spiral = hexSpiral(hex(0, 0), 2);
    expect(spiral).toHaveLength(19); // 1 + 6 + 12
    expect(unique(spiral).size).toBe(19);
    expect(distance(hex(0, 0), spiral[0])).toBe(0);
  });

  it('contains all rings up to radius, each at the right distance', () => {
    const center = hex(1, 1);
    const spiral = hexSpiral(center, 3);
    expect(spiral).toHaveLength(1 + 6 + 12 + 18);
    const countsByDistance = new Map<number, number>();
    for (const h of spiral) {
      const d = distance(center, h);
      countsByDistance.set(d, (countsByDistance.get(d) ?? 0) + 1);
    }
    expect([...countsByDistance.entries()].sort()).toEqual([
      [0, 1],
      [1, 6],
      [2, 12],
      [3, 18],
    ]);
  });
});

describe('hexLine', () => {
  it('length is distance+1 and consecutive entries are neighbors', () => {
    const pairs: Array<[typeof hexA, typeof hexB]> = [];
    var hexA = hex(-2, 5);
    // deterministic spread of endpoints
    const ends = [
      hex(4, -2),
      hex(-5, -1),
      hex(0, 6),
      hex(7, -7),
      hex(1, 1),
    ];
    for (const end of ends) pairs.push([hexA, end]);
    pairs.push([hex(3, 3), hex(-4, 2)]);
    pairs.push([hex(0, 0), hex(0, 0)]);

    for (const [a, b] of pairs) {
      const line = hexLine(a, b);
      expect(line).toHaveLength(distance(a, b) + 1);
      expect(line[0]).toEqual(a);
      expect(line[line.length - 1]).toEqual(b);
      for (let i = 0; i < line.length - 1; i++) {
        expect(distance(line[i], line[i + 1])).toBe(1);
      }
    }
  });

  it('is symmetric: reversed input yields reversed line', () => {
    const a = hex(-3, 1);
    const b = hex(5, -4);
    const forward = hexLine(a, b);
    const backward = hexLine(b, a).reverse();
    expect(forward.map(key)).toEqual(backward.map(key));
  });
});
"})
